import{_ as a,c as t,o,aj as r}from"./chunks/framework.C2N4vG9O.js";const p=JSON.parse('{"title":"Core components","description":"Follow one movie impression from feature encoding to a training batch and a click score.","frontmatter":{"title":"Core components","description":"Follow one movie impression from feature encoding to a training batch and a click score."},"headers":[],"relativePath":"core/intro.md","filePath":"en/core/intro.md"}'),i={name:"core/intro.md"};function n(c,e,s,h,d,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="core-components" tabindex="-1">Core components <a class="header-anchor" href="#core-components" aria-label="Permalink to “Core components”">​</a></h1><p>Consider a movie impression. You know which movies the user has already watched, which movie you showed them, and whether they clicked it. To train a ranker, first turn that record into numbers the model can read. The trainer can then compare the predicted click score with the observed label to calculate the loss.</p><h2 id="from-one-record-to-a-training-batch" tabindex="-1">From one record to a training batch <a class="header-anchor" href="#from-one-record-to-a-training-batch" aria-label="Permalink to “From one record to a training batch”">​</a></h2><ol><li><strong>Encode the features.</strong> Suppose movie <code>M42</code> has ID <code>3</code> in your vocabulary. If it is the user&#39;s only watched movie and the history length is three, <code>hist_movie_id</code> is <code>[3, 0, 0]</code>. The last two positions are padding. Use the same movie vocabulary for candidates and histories. <a href="/torch-rechub/core/features.html">Feature definitions</a></li><li><strong>Build a batch.</strong> With <code>B</code> records, the candidate IDs have shape <code>[B]</code> and the histories have shape <code>[B, 3]</code>. <code>DataGenerator</code> puts the features in a dictionary and passes them to the trainer with the <code>B</code> click labels. <a href="/torch-rechub/core/data.html">Loading data</a></li><li><strong>Train the ranker.</strong> The model scores each record in the feature dictionary. <code>CTRTrainer.fit(train_dl, val_dl)</code> updates the weights on the training set and measures AUC on the validation set after each epoch. <a href="/torch-rechub/core/evaluation.html">Training and evaluation</a></li></ol><h2 id="trainers-for-other-tasks" tabindex="-1">Trainers for other tasks <a class="header-anchor" href="#trainers-for-other-tasks" aria-label="Permalink to “Trainers for other tasks”">​</a></h2><p>For retrieval, you need to find candidates in the item catalog. <code>MatchDataGenerator</code> prepares separate inputs for users and items. Once the two towers are trained, <code>MatchTrainer</code> can compute the embeddings for each side. <a href="/torch-rechub/tutorials/retrieval.html">Retrieval tutorial</a></p><p>If a record has several labels, you can still batch it with <code>DataGenerator</code>. Configure the tasks in <code>MTLTrainer</code> in the same order as the label columns so you can read each task&#39;s metrics separately. <a href="/torch-rechub/tutorials/pipeline.html">Multi-task tutorial</a></p><p>HSTU and HLLM use <code>SequenceDataGenerator</code> and <code>SeqTrainer</code> to predict the next item. RQ-VAE learns semantic IDs for items, and TIGER learns to generate those IDs. Each has its own training script. <a href="/torch-rechub/models/generative.html">Generative models</a></p>',8)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
